-- Hand-written parts. Prisma cannot express check constraints and triggers, so they are added here by hand.

-- The table holds a single row.
ALTER TABLE "AuthSecret" ADD CONSTRAINT "AuthSecret_single_row" CHECK ("id" = 1);

-- The type of an account never changes: the trigger refuses every update that changes it, so that no code and no
-- command can change it after the account was created. Updates that leave the type as it is, such as those of Better
-- Auth, pass.
CREATE FUNCTION "User_keep_type"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."type" IS DISTINCT FROM OLD."type" THEN
    RAISE EXCEPTION 'the type of an account cannot be changed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "User_keep_type"
BEFORE UPDATE ON "User"
FOR EACH ROW EXECUTE FUNCTION "User_keep_type"();

-- An admin never has a role on a folder: the trigger refuses every insert and every update of a role whose user is an
-- admin, so that no code, command or crafted request can give an admin a role. The type of an account never changes
-- (the trigger `User_keep_type` above), so the check at insert and update is enough.
CREATE FUNCTION "FolderRole_no_admin"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "User" WHERE "id" = NEW."userId" AND "type" = 'admin') THEN
    RAISE EXCEPTION 'an admin cannot have a role on a folder' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "FolderRole_no_admin"
BEFORE INSERT OR UPDATE ON "FolderRole"
FOR EACH ROW EXECUTE FUNCTION "FolderRole_no_admin"();
